do $$
declare v uuid;
begin
  select id into v from public.venues where slug = 'cnca-2026';
  if v is not null then
    update public.venues set details = '{"policies": [{"title": "Original work", "text": "Papers must not be under review elsewhere or already published. A similarity check runs on every PDF; overlap above 30% (references excluded) is sent to the chairs.", "tag": "Required"}, {"title": "Author names on the PDF", "text": "Reviews are single-blind: reviewers see your names and affiliations, you don''t see theirs."}, {"title": "Author list", "text": "Authors can be added or reordered until the deadline. After it, changes need the chairs'' approval."}, {"title": "AI tools", "text": "Tools that correct language are allowed. Text, figures or results generated by AI must be declared in the acknowledgements; AI tools can''t be authors."}, {"title": "Registration and presentation", "text": "Each accepted paper needs one author registered at the full rate by the final-version deadline, and must be presented in person. Papers not presented are removed from the proceedings.", "tag": "No-show rule"}, {"title": "Conflicts of interest", "text": "Declare co-authors from the last 3 years and colleagues at your institution. Reviewers with a conflict are never assigned your paper."}], "publication": {"proceedings": "Accepted and presented papers are published open access in the CNCA proceedings (AMCA, with ISSN).", "copyright": "Signed online from your paper page after acceptance (IEEE eCF or the publisher''s form)."}}'::jsonb || details,
      public_info = jsonb_build_object(
        'attending', '{"conduct": "All participants follow the code of conduct of the sponsoring society. Report concerns at the registration desk or by email to the organizers; reports are handled confidentially.", "accessibility": "All rooms are step-free. Tell the organizers about access needs when you register; a quiet room and a parents'' room are available during the conference.", "visa": "Check the entry rules for Mexico for your passport. Invitation letters for visa applications are issued from your registration page once the fee is paid; apply at least 8 weeks before travel.", "registration_note": "Indicative fees for planning; the organizers'' registration site has the final amounts and dates.", "hotels_note": "Hotels near the venue fill up early in conference week: book once your paper is accepted. Rates negotiated by the organizers are listed on the official site.", "grants": "AMCA offers reduced fees and travel support for student members presenting a paper; apply when you register."}'::jsonb || coalesce(public_info->'attending', '{}'),
        'travel', '{"directions": [{"mode": "plane", "title": "Monterrey International Airport (MTY)", "time": "30–40 min", "note": "About 25 km from Ciudad Universitaria; authorised airport taxis and ride-hailing."}, {"mode": "car", "title": "From downtown Monterrey", "time": "20 min", "note": "Via Av. Universidad; parking at FIME with your badge."}]}'::jsonb || coalesce(public_info->'travel', '{}')) || (public_info - 'attending' - 'travel'),
      review_mode = coalesce(review_mode, 'Single-blind')
    where id = v;
