    where venue_id = v and not exists (select 1 from jsonb_array_elements(fee_types) f where f->>'early' is not null);
    insert into public.submission_types (venue_id, name, description, pages, extra_pages, blind_override, sort) values (v, 'Regular paper', 'Full paper on completed research.', 6, 2, 'single', 0) on conflict (venue_id, name) do nothing;
    insert into public.submission_types (venue_id, name, description, pages, extra_pages, blind_override, sort) values (v, 'Invited session paper', 'Paper for an accepted invited session; use the session code.', 6, 2, 'single', 1) on conflict (venue_id, name) do nothing;
